// @FIGURE_CODE_BEGIN
// ── ELEMENT SPEC ───────────────────────────────────────────────────────────
// green surface patch    → PlaneGeometry(8,8) rotated into XZ, MeshBasicMaterial #66EE00
// black patch outline    → 4 × BoxGeometry bars (0.06 thick) black, along the 4 edges
// hit point ellipse      → TorusGeometry(0.25,0.022) flat in plane at origin, black
// normal n               → arrow group (Cylinder shaft r=.04 + Cone head .38) black, L=1.3, +Y
// right-angle marker     → 2 × thin BoxGeometry forming an L (0.28) in the n / screen-right plane
// tangent p              → arrow group black, L=1.1, in plane, world (-1,0,-1)/√2  → screen up-left
// tangent q              → arrow group black, L=1.1, in plane, world ( 1,0,-1)/√2  → screen up-right (90° from p)
// incoming ray bar       → CylinderGeometry(0.16→0.05, len 4.4) vertex-coloured yellow→orange→red
// incoming arrowhead     → ConeGeometry(0.17,0.55) red #FF2200, apex exactly at the origin
// ray drag picker        → invisible Cylinder r=0.42 along the ray (raycast target only)
// lobe arrows (16)       → arrow groups #46C020 opacity .72, length from the BRDF formula
// main outgoing arrow    → arrow group #1A7A1A opaque, bigger head, mirror direction, L≤2.6
// neighbour arrow        → arrow group #7ADB6B opacity .75, 25° from the mirror direction
// drag hemisphere hint   → SphereGeometry(2.6, hemisphere) wireframe, opacity .12
// labels                 → addLabel: ℓ_in(λ), ℓ_out=F(ℓ_in,n,λ,p,q), n, p, q  (serif, italic)
// ───────────────────────────────────────────────────────────────────────────

const UP = new THREE.Vector3(0, 1, 0);
const ORIGIN = new THREE.Vector3(0, 0, 0);
const root = new THREE.Group();
scene.add(root);

/* ── mutable state (declared first: updateAll() touches it) ──────────────── */
const LIGHT0 = new THREE.Vector3(-3.2, 4.4, 1.6).normalize();
const lightDir = LIGHT0.clone();
const mirrorDir = new THREE.Vector3();
let roughness = 0.35;
let matMode = 'glossy';
let labIn = null, labOut = null;
let roughTween = null;
let sweep = null;
let dragging = false;
let stepIdx = 0;

/* ── surface patch ───────────────────────────────────────────────────────── */
const planeMesh = new THREE.Mesh(
  new THREE.PlaneGeometry(8, 8),
  new THREE.MeshBasicMaterial({ color: 0x66EE00, side: THREE.DoubleSide })
);
planeMesh.rotation.x = -Math.PI / 2;
planeMesh.position.y = -0.006;
root.add(planeMesh);

const blackMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
const BT = 0.06, HALF = 4;
function addBar(w, dp, x, z) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, 0.02, dp), blackMat);
  m.position.set(x, 0.001, z);
  root.add(m);
}
addBar(8 + BT, BT, 0, -HALF);
addBar(8 + BT, BT, 0, HALF);
addBar(BT, 8 + BT, -HALF, 0);
addBar(BT, 8 + BT, HALF, 0);

/* ── hit point ellipse ───────────────────────────────────────────────────── */
const hitRing = new THREE.Mesh(new THREE.TorusGeometry(0.25, 0.022, 8, 44), blackMat);
hitRing.rotation.x = -Math.PI / 2;
hitRing.position.y = 0.012;
root.add(hitRing);

/* ── reusable arrow builder ──────────────────────────────────────────────── */
function makeArrow(o) {
  const g = new THREE.Group();
  const transparent = (o.opacity !== undefined && o.opacity < 1);
  const mat = new THREE.MeshBasicMaterial({
    color: o.color, transparent, opacity: o.opacity === undefined ? 1 : o.opacity,
    depthWrite: !transparent
  });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(o.shaftR, o.shaftR, 1, 12), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(o.headR, o.headLen, 18), mat);
  g.add(shaft); g.add(head);
  g.userData = { shaft, head, mat, headLen: o.headLen };
  root.add(g);
  return g;
}
function setArrow(g, dir, L) {
  const u = g.userData;
  const hl = Math.min(u.headLen, Math.max(0.08, L * 0.55));
  const s = Math.max(0.0001, L - hl);
  u.shaft.scale.y = s;
  u.shaft.position.y = s / 2;
  u.head.scale.set(1, hl / u.headLen, 1);
  u.head.position.y = L - hl / 2;
  g.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
  g.visible = L > 0.02;
}

/* ── local frame: n, p, q ────────────────────────────────────────────────── */
const nArrow = makeArrow({ color: 0x000000, shaftR: 0.04, headR: 0.15, headLen: 0.38 });
setArrow(nArrow, UP, 1.3);

const pDir = new THREE.Vector3(-1, 0, -1).normalize();   // screen up-left
const qDir = new THREE.Vector3(1, 0, -1).normalize();    // screen up-right, 90° from p
const pArrow = makeArrow({ color: 0x000000, shaftR: 0.04, headR: 0.15, headLen: 0.38 });
const qArrow = makeArrow({ color: 0x000000, shaftR: 0.04, headR: 0.15, headLen: 0.38 });
setArrow(pArrow, pDir, 1.1);
setArrow(qArrow, qDir, 1.1);

/* ── right-angle marker (plane of n and the screen-right in-plane dir) ───── */
const raGroup = new THREE.Group();
const RA = 0.28, RT = 0.026;
const raV = new THREE.Mesh(new THREE.BoxGeometry(RT, RA + RT, RT), blackMat);
raV.position.set(RA, RA / 2, 0);
const raH = new THREE.Mesh(new THREE.BoxGeometry(RA + RT, RT, RT), blackMat);
raH.position.set(RA / 2, RA, 0);
raGroup.add(raV); raGroup.add(raH);
raGroup.rotation.y = Math.atan2(0.325, 0.946);   // local +X → screen-right in the plane
root.add(raGroup);

/* ── incoming ray ────────────────────────────────────────────────────────── */
const RAY_LEN = 4.4;
const rayGeo = new THREE.CylinderGeometry(0.16, 0.05, 1, 24, 12, false);
rayGeo.translate(0, 0.5, 0);
{
  const pos = rayGeo.attributes.position;
  const cols = new Float32Array(pos.count * 3);
  const cA = new THREE.Color(0xFF2200), cB = new THREE.Color(0xFF8C00), cC = new THREE.Color(0xFFE000);
  const tmp = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const t = Math.min(1, Math.max(0, pos.getY(i)));
    if (t < 0.5) tmp.copy(cA).lerp(cB, t / 0.5);
    else tmp.copy(cB).lerp(cC, (t - 0.5) / 0.5);
    cols[i * 3] = tmp.r; cols[i * 3 + 1] = tmp.g; cols[i * 3 + 2] = tmp.b;
  }
  rayGeo.setAttribute('color', new THREE.BufferAttribute(cols, 3));
}
const rayGroup = new THREE.Group();
const rayBar = new THREE.Mesh(rayGeo, new THREE.MeshBasicMaterial({ vertexColors: true }));
rayBar.scale.y = RAY_LEN;
rayGroup.add(rayBar);
const rayHead = new THREE.Mesh(
  new THREE.ConeGeometry(0.17, 0.55, 20),
  new THREE.MeshBasicMaterial({ color: 0xFF2200 })
);
rayHead.position.set(0, 0.275, 0);
rayHead.rotation.x = Math.PI;                 // apex at the hit point
rayGroup.add(rayHead);
const rayPick = new THREE.Mesh(
  new THREE.CylinderGeometry(0.42, 0.42, RAY_LEN, 10),
  new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })
);
rayPick.position.y = RAY_LEN / 2;
rayGroup.add(rayPick);
root.add(rayGroup);

/* ── outgoing lobe directions (dense near grazing, as in the source) ─────── */
const LOBE_DIRS = [];
[{ el: 6, n: 7, off: 10 }, { el: 24, n: 5, off: 46 }, { el: 48, n: 3, off: 22 }, { el: 72, n: 1, off: 100 }]
  .forEach(r => {
    for (let i = 0; i < r.n; i++) {
      const az = THREE.MathUtils.degToRad(r.off + i * 360 / r.n);
      const el = THREE.MathUtils.degToRad(r.el);
      LOBE_DIRS.push(new THREE.Vector3(Math.cos(az) * Math.cos(el), Math.sin(el), Math.sin(az) * Math.cos(el)));
    }
  });
const lobeArrows = LOBE_DIRS.map(() =>
  makeArrow({ color: 0x46C020, shaftR: 0.035, headR: 0.15, headLen: 0.38, opacity: 0.72 }));
const nbrArrow = makeArrow({ color: 0x7ADB6B, shaftR: 0.042, headR: 0.17, headLen: 0.44, opacity: 0.75 });
const mainArrow = makeArrow({ color: 0x1A7A1A, shaftR: 0.05, headR: 0.20, headLen: 0.50 });

/* ── hemisphere hint ─────────────────────────────────────────────────────── */
const hemiWire = new THREE.Mesh(
  new THREE.SphereGeometry(2.6, 24, 10, 0, Math.PI * 2, 0, Math.PI / 2),
  new THREE.MeshBasicMaterial({ color: 0x225522, wireframe: true, transparent: true, opacity: 0.13, depthWrite: false })
);
hemiWire.visible = false;
root.add(hemiWire);

/* ── BRDF evaluation ─────────────────────────────────────────────────────── */
function materialParams() {
  const r = Math.min(1, Math.max(0.02, roughness));
  let kd, ks;
  if (matMode === 'lambert') { kd = 1; ks = 0; }
  else if (matMode === 'mirror') { kd = 0.08 * r; ks = 1 - 0.08 * r; }
  else { kd = r; ks = 1 - r; }
  const s = Math.min(20000, 2 / (r * r) - 2);
  return { kd, ks, s };
}

function updateAll() {
  rayGroup.quaternion.setFromUnitVectors(UP, lightDir);

  const { kd, ks, s } = materialParams();
  const cosTi = Math.max(0, lightDir.y);
  mirrorDir.set(-lightDir.x, lightDir.y, -lightDir.z).normalize();
  const maxRaw = 0.55 + 2.2 * (kd / Math.PI + ks);
  const scl = 2.6 / maxRaw;

  const lenFor = (dir) => {
    const ca = Math.max(0, dir.dot(mirrorDir));
    const fr = kd / Math.PI + ks * Math.pow(ca, s);
    return Math.max(0.12, (0.55 + 2.2 * fr * cosTi) * scl);
  };

  for (let i = 0; i < lobeArrows.length; i++) setArrow(lobeArrows[i], LOBE_DIRS[i], lenFor(LOBE_DIRS[i]));

  const nbrDir = mirrorDir.clone().applyAxisAngle(UP, THREE.MathUtils.degToRad(-25)).normalize();
  setArrow(nbrArrow, nbrDir, lenFor(nbrDir));
  const mainLen = lenFor(mirrorDir);
  setArrow(mainArrow, mirrorDir, mainLen);

  if (labIn) labIn.pos.copy(lightDir).multiplyScalar(RAY_LEN * 0.78);
  if (labOut) labOut.pos.copy(mirrorDir).multiplyScalar(mainLen);
}
updateAll();

/* ── camera (after all geometry) ─────────────────────────────────────────── */
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 6, z: 40 }, heightFraction: 0.85 });
controls.minPolarAngle = THREE.MathUtils.degToRad(10);
controls.maxPolarAngle = THREE.MathUtils.degToRad(86);

/* ── labels ──────────────────────────────────────────────────────────────── */
const SER = 'font-family:Georgia,"Times New Roman",serif;';
labIn = addLabel(
  `<span style="${SER}font-style:italic">&#8467;<sub style="font-size:.72em">in</sub>(&lambda;)</span>`,
  lightDir.clone().multiplyScalar(RAY_LEN * 0.78), { fontSize: '21px', offset: [62, -2] });
labOut = addLabel(
  `<span style="${SER}font-style:italic">&#8467;<sub style="font-size:.72em">out</sub>=F(&#8467;<sub style="font-size:.72em">in</sub>,<b style="font-style:normal">n</b>,&lambda;,<b style="font-style:normal">p</b>,<b style="font-style:normal">q</b>)</span>`,
  mirrorDir.clone().multiplyScalar(2.6), { fontSize: '19px', offset: [112, -14] });
addLabel(`<b style="${SER}">n</b>`, new THREE.Vector3(0, 1.3, 0), { fontSize: '20px', offset: [-16, -12] });
addLabel(`<b style="${SER}">p</b>`, pDir.clone().multiplyScalar(1.12), { fontSize: '20px', offset: [-18, -10] });
addLabel(`<b style="${SER}">q</b>`, qDir.clone().multiplyScalar(1.12), { fontSize: '20px', offset: [20, -8] });
updateAll();

/* ── hover / click explanations ──────────────────────────────────────────── */
registerInteractive(planeMesh, {
  title: 'Surface patch',
  tooltip: 'The reflecting surface',
  body: 'A small patch of surface around the hit point. The BRDF is defined locally at this point, in the frame given by n, p and q.'
});
registerInteractive(nArrow, {
  title: 'Surface normal n',
  tooltip: 'Surface normal n',
  body: 'The unit normal at the hit point. Together with the in-plane tangents p and q it defines the local frame in which the BRDF F(ℓ_in, n, λ, p, q) is expressed — anisotropic materials (brushed metal, fabric) depend on p and q, isotropic ones do not.'
});
registerInteractive(pArrow, {
  title: 'Tangent p', tooltip: 'In-plane tangent p',
  body: 'One of the two orthogonal tangent vectors of the local surface frame. p ⟂ q ⟂ n.'
});
registerInteractive(qArrow, {
  title: 'Tangent q', tooltip: 'In-plane tangent q',
  body: 'The second tangent, exactly 90° from p about the normal. Under this oblique view the right angle between them is foreshortened.'
});
registerInteractive(rayPick, {
  title: 'Incoming radiance ℓ_in(λ)',
  tooltip: 'Drag me to move the light',
  body: 'The incident ray of wavelength λ. Drag it around the hemisphere: the outgoing lobe follows the mirror direction and shrinks as cos θ_i when the light approaches grazing incidence.'
});
registerInteractive(mainArrow, {
  title: 'Outgoing radiance ℓ_out',
  tooltip: 'Dominant outgoing direction',
  body: 'The longest arrow, near the mirror direction. Its length is L = 0.55 + 2.2·f_r(ω_i, ω_o)·cos θ_i — the reflected radiance in that direction.'
});

/* ── controls ────────────────────────────────────────────────────────────── */
const matSel = document.getElementById('matSel');
const roughSlider = document.getElementById('rough');
const roughVal = document.getElementById('roughVal');
const chkHemi = document.getElementById('chkHemi');

function setRoughness(v, syncSlider = true) {
  roughness = Math.min(1, Math.max(0.02, v));
  if (syncSlider) roughSlider.value = roughness.toFixed(2);
  roughVal.textContent = roughness.toFixed(2);
  updateAll();
}
roughSlider.addEventListener('input', () => { roughTween = null; setRoughness(parseFloat(roughSlider.value), false); });
matSel.addEventListener('change', () => { matMode = matSel.value; updateAll(); });
chkHemi.addEventListener('change', () => { hemiWire.visible = chkHemi.checked; });
document.getElementById('btnLightReset').addEventListener('click', () => {
  sweep = null; lightDir.copy(LIGHT0); updateAll();
});

/* ── drag the incoming ray ───────────────────────────────────────────────── */
const dragRC = new THREE.Raycaster();
const dragNDC = new THREE.Vector2();
const dragSphere = new THREE.Sphere(ORIGIN, 2.6);

function pointerNDC(ev) {
  const rect = canvas.getBoundingClientRect();
  dragNDC.x = ((ev.clientX - rect.left) / rect.width) * 2 - 1;
  dragNDC.y = -((ev.clientY - rect.top) / rect.height) * 2 + 1;
  dragRC.setFromCamera(dragNDC, camera);
}
function dirFromPointer(ev) {
  pointerNDC(ev);
  const pt = new THREE.Vector3();
  if (!dragRC.ray.intersectSphere(dragSphere, pt)) dragRC.ray.closestPointToPoint(ORIGIN, pt);
  if (pt.lengthSq() < 1e-8) return null;
  const dir = pt.normalize();
  const minY = Math.sin(THREE.MathUtils.degToRad(8));
  if (dir.y < minY) {
    const h = Math.sqrt(Math.max(1e-6, 1 - minY * minY));
    const hv = new THREE.Vector3(dir.x, 0, dir.z);
    if (hv.lengthSq() < 1e-9) hv.set(1, 0, 0);
    hv.normalize().multiplyScalar(h);
    dir.set(hv.x, minY, hv.z);
  }
  return dir.normalize();
}

canvas.addEventListener('pointerdown', (ev) => {
  pointerNDC(ev);
  const hits = dragRC.intersectObjects([rayPick, rayBar, rayHead], true);
  if (hits.length) {
    dragging = true;
    sweep = null;
    controls.enabled = false;
    hemiWire.visible = true;
    canvas.style.cursor = 'grabbing';
  }
});
window.addEventListener('pointermove', (ev) => {
  if (!dragging) return;
  const dd = dirFromPointer(ev);
  if (dd) { lightDir.copy(dd); updateAll(); }
});
window.addEventListener('pointerup', () => {
  if (!dragging) return;
  dragging = false;
  controls.enabled = true;
  hemiWire.visible = chkHemi.checked || !!sweep;
  canvas.style.cursor = 'default';
});

/* ── guided demo ─────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: '1 · The incoming ray and local frame',
    text: 'A single light ray ℓ_in(λ) strikes the green surface at one point. The normal n and the in-plane vectors p and q define the local coordinate frame in which the BRDF is expressed.',
    mode: 'glossy', rough: 0.35, sweep: false, light: LIGHT0
  },
  {
    title: '2 · Perfectly diffuse surface',
    text: 'For a Lambertian surface every outgoing arrow has nearly the same length: incoming energy is scattered equally into all directions of the hemisphere.',
    mode: 'lambert', rough: 1, sweep: false
  },
  {
    title: '3 · Glossy surface: a lobe appears',
    text: 'Increasing specularity concentrates the arrows into a lobe around the mirror direction — this dominant arrow is the ℓ_out drawn in the original figure.',
    mode: 'glossy', rough: 0.35, sweep: false
  },
  {
    title: '4 · Near-mirror limit',
    text: 'As roughness goes to zero the lobe collapses to a single long arrow: specular reflection is the degenerate case of the general BRDF F(ℓ_in, n, λ, p, q).',
    mode: 'mirror', rough: 0.05, sweep: false
  },
  {
    title: '5 · Move the light',
    text: 'Drag the incoming ray around the hemisphere: the lobe follows the mirror direction and its overall magnitude falls off as cos θ_i when the light approaches grazing incidence.',
    mode: 'glossy', rough: 0.5, sweep: true
  }
];
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  stepTitle.textContent = s.title;
  stepText.textContent = s.text;
  matMode = s.mode;
  matSel.value = s.mode;
  roughTween = { from: roughness, to: s.rough, t0: performance.now(), dur: 700 };
  if (s.light) lightDir.copy(s.light);
  sweep = s.sweep ? { base: lightDir.clone(), t0: performance.now() } : null;
  hemiWire.visible = chkHemi.checked || !!sweep;
  updateAll();
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

/* ── tween / sweep loop ──────────────────────────────────────────────────── */
function figTick(now) {
  requestAnimationFrame(figTick);
  if (roughTween) {
    const k = Math.min(1, (now - roughTween.t0) / roughTween.dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    setRoughness(roughTween.from + (roughTween.to - roughTween.from) * e);
    if (k >= 1) roughTween = null;
  }
  if (sweep && !dragging) {
    const a = THREE.MathUtils.degToRad(42) * Math.sin((now - sweep.t0) / 4200 * Math.PI * 2);
    lightDir.copy(sweep.base).applyAxisAngle(UP, a).normalize();
    updateAll();
  }
}
requestAnimationFrame(figTick);
